def weather_get_weather_alerts(location, severity=None):
    import json, os

    def _lookup(location):
        import json, os
        db = json.load(open(os.path.join(_DB, 'weather.json'), encoding='utf-8'))
        key = (location or '').replace(' ', '')
        return db, db['by_location'].get(key, db['default'])
